class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        List<Integer>[] buckets = new List[nums.length + 1];
        for (int i = 0; i < buckets.length; i++) {
            buckets[i] = new ArrayList<>();
        }

        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            buckets[entry.getValue()].add(entry.getKey());
        }

        int[] result = new int[k];
        int idx = 0;

        for (int i = buckets.length - 1; i >= 0 && idx < k; i--) {
            for (int num : buckets[i]) {
                result[idx++] = num;
                if (idx == k) break;
            }
        }

        return result;
    }
}

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        PriorityQueue<Map.Entry<Integer, Integer>> minHeap = 
            new PriorityQueue<>((a, b) -> a.getValue() - b.getValue());

        for (Map.Entry<Integer, Integer> entry : freqMap.entrySet()) {
            minHeap.offer(entry);
            if (minHeap.size() > k) {
                minHeap.poll();
            }
        }

        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = minHeap.poll().getKey();
        }

        return result;
    }
}

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        int[] unique = new int[freqMap.size()];
        int i = 0;
        for (int num : freqMap.keySet()) {
            unique[i++] = num;
        }

        int n = unique.length;
        quickSelect(unique, freqMap, 0, n - 1, n - k);

        return Arrays.copyOfRange(unique, n - k, n);
    }

    private void quickSelect(int[] arr, Map<Integer, Integer> freq, int left, int right, int k) {
        if (left >= right) return;

        int pivot = partition(arr, freq, left, right);

        if (pivot == k) return;
        else if (pivot < k) quickSelect(arr, freq, pivot + 1, right, k);
        else quickSelect(arr, freq, left, pivot - 1, k);
    }

    private int partition(int[] arr, Map<Integer, Integer> freq, int left, int right) {
        int pivotFreq = freq.get(arr[right]);
        int i = left;

        for (int j = left; j < right; j++) {
            if (freq.get(arr[j]) < pivotFreq) {
                swap(arr, i, j);
                i++;
            }
        }
        swap(arr, i, right);
        return i;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
